insert into public.questions (id, chapter_id, topic_id, year, type, content, choices, images, difficulty, language, origin, source, verification)
values ('bacc2020-2022-4000-8000-000000000001', 'kh-grade12-social-khmer-literature-past-papers', null, 2022, 'open', 'ចូរពន្យល់ និងបកស្រាយពី «ទស្សនៈស្នេហាជាតិនៅក្នុងអក្សរសិល្ប៍ខ្មែរ» ដោយរកឧទាហរណ៍ក្នុងអក្សរសិល្ប៍ខ្មែរមកបញ្ជាក់។', '[]'::jsonb, '[]'::jsonb, null, 'km', 'official-past-paper', 'BacII 2022 (2022-12-05), social science track khmer literature, Ministry of Education, Youth and Sport. Typed by Meh Rean from one copy: retyped by ជៀប គីមឈរ (github.com/HELMAB/bacii). Not yet checked against the Ministry''s original.', 'needs-review')
on conflict (id) do update set chapter_id = excluded.chapter_id, content = excluded.content, images = excluded.images, language = excluded.language, source = excluded.source;
insert into public.exam_paper_questions (paper_id, question_id, position, points)
values ('bacc2020-2022-4000-8000-000000000000', 'bacc2020-2022-4000-8000-000000000001', 1, 125)
on conflict (paper_id, question_id) do update set position = excluded.position, points = excluded.points;

insert into public.question_solutions (question_id, answer, correct_choice, numeric_answer, numeric_tolerance, steps, origin, source, verification)
values ('bacc2020-2022-4000-8000-000000000001', 'អត្ថបទគំរូ (AI)៖ ទស្សនៈស្នេហាជាតិក្នុងអក្សរសិល្ប៍ខ្មែរ គឺការលើកតម្កើងចិត្តស្រឡាញ់ ការពារ និងការលះបង់ចំពោះមាតុភូមិ ទឹកដី ភាសា វប្បធម៌ និងប្រជាជាតិខ្មែរ។ ឧទាហរណ៍៖ រាមកេរ្តិ៍ ធនញ្ជ័យ តេជោយ៉ត (និងបទនគររាជ)។ ចុច «Show the working» ដើម្បីអានទាំងស្រុង។', null, null, null, '[{"content":"ទម្រង់៖ សេចក្តីផ្តើម (លំនាំ ចំណូល ចំណោទបញ្ហា) · តួសេចក្តី (ពន្យល់ពាក្យ ពន្យល់ន័យ បំណកស្រាយ ឧទាហរណ៍បីរឿង សរុបមតិ) · សេចក្តីបញ្ចប់ (វាយតម្លៃ និងមតិផ្ទាល់ខ្លួន)។"},{"content":"សេចក្តីផ្តើម៖ ប្រទេសកម្ពុជាបានឆ្លងកាត់ប្រវត្តិសាស្ត្ររុងរឿង និងលំបាក។ ក្នុងគ្រប់សម័យ អក្សរសិល្ប៍ខ្មែរបានជួយបណ្តុះចិត្តស្រឡាញ់ជាតិ។ តើ «ទស្សនៈស្នេហាជាតិនៅក្នុងអក្សរសិល្ប៍ខ្មែរ» មានន័យដូចម្តេច ហើយបង្ហាញតាមរបៀបណា?"},{"content":"ពន្យល់ពាក្យ និងន័យ៖ ទស្សនៈ គឺគំនិត ឬការយល់ឃើញ។ ស្នេហាជាតិ គឺចិត្តស្រឡាញ់ ស្មោះត្រង់ និងហ៊ានលះបង់ចំពោះមាតុភូមិ។ ទស្សនៈស្នេហាជាតិក្នុងអក្សរសិល្ប៍ គឺគំនិតស្រឡាញ់ជាតិ ដែលអ្នកនិពន្ធបញ្ចូលក្នុងស្នាដៃ ដើម្បីដាស់ស្មារតីអ្នកអាន។"},{"content":"បំណកស្រាយ៖ អក្សរសិល្ប៍បង្ហាញស្នេហាជាតិតាមរយៈ៖ (ក) ការលើកតម្កើងទឹកដី វប្បធម៌ ប្រពៃណី និងអត្តសញ្ញាណជាតិ (ខ) ការអប់រំឲ្យគិតគូរជាតិមាតុភូមិ (គ) ការលើកតម្កើងវីរជនដែលតស៊ូការពារទឹកដី និងឯករាជ្យ (ឃ) ការណែនាំឲ្យចូលរួមកសាង អភិវឌ្ឍ និងថែរក្សាជាតិ ព្រមទាំងប្រឆាំងនឹងអ្វីដែលនាំអន្តរាយដល់ជាតិ។"},{"content":"ឧទាហរណ៍ទី១៖ រឿងរាមកេរ្តិ៍៖ ស្នាដៃដ៏ល្បីដែលខ្មែរបានកែច្នៃជាសម្បត្តិវប្បធម៌ខ្លួន (ល្ខោនខោល ចម្លាក់អង្គរ)។ ការតស៊ូរបស់ព្រះរាម និងហនុមានដើម្បីការពារយុត្តិធម៌ បណ្តុះស្មារតីការពារនគរ និងមោទនភាពវប្បធម៌ជាតិ។"},{"content":"ឧទាហរណ៍ទី២៖ រឿងធនញ្ជ័យ (រឿងប្រជាប្រិយ)៖ ធនញ្ជ័យប្រើប្រាជ្ញាឈ្លាសវៃ ដោះស្រាយបញ្ហាផ្សេងៗ យកឈ្នះអ្នកមានអំណាច ហើយថែមទាំងការពារកិត្តិយសស្រុកខ្មែរពីការប្រកួតប្រាជ្ញាជាមួយបរទេស។ រឿងនេះបង្រៀនថា ចំណេះ និងប្រាជ្ញា ជាអាវុធដែលខ្លាំងជាងកម្លាំង។ នេះបង្ហាញពីមោទនភាព និងការការពារកិត្តិយសជាតិ។"},{"content":"ឧទាហរណ៍ទី៣៖ រឿងតេជោយ៉ត និងរឿងវីរជនខ្មែរផ្សេងៗ៖ លើកតម្កើងអ្នកដែលក្លាហាន ហ៊ានលះបង់ ដើម្បីការពារទឹកដីខ្មែរពីសត្រូវ ដើម្បីជាគំរូដល់កូនចៅ។"},{"content":"ឧទាហរណ៍ទី៤៖ បទនគររាជ (ទំនុកច្រៀងដោយសម្តេចព្រះសង្ឃរាជ ជួន ណាត)៖ សរសើរភាពរុងរឿងនៃប្រាសាទ និងអាណាចក្រខ្មែរ ហើយបួងសួងឲ្យជាតិខ្មែរគង់វង្ស។"},{"content":"សរុបមតិ៖ អក្សរសិល្ប៍ខ្មែរ ទាំងបុរាណ ប្រជាប្រិយ និងទំនើប សុទ្ធតែមានទស្សនៈស្នេហាជាតិ ដែលអប់រំឲ្យស្រឡាញ់ ការពារ និងកសាងជាតិមាតុភូមិ។"},{"content":"សេចក្តីបញ្ចប់៖ ទស្សនៈស្នេហាជាតិក្នុងអក្សរសិល្ប៍មានតម្លៃខ្ពស់។ ក្នុងនាមជាសិស្ស យើងត្រូវសិក្សាអក្សរសិល្ប៍ជាតិ ថែរក្សាភាសា និងវប្បធម៌ ហើយខិតខំរៀនសូត្រ ដើម្បីចូលរួមកសាងប្រទេសកម្ពុជាឲ្យរីកចម្រើន។"},{"content":"ចំណាំ៖ នេះជាអត្ថបទគំរូមួយក្នុងចំណោមចម្លើយល្អៗជាច្រើន។ សិស្សអាចលើករឿងផ្សេងទៀតដែលបានរៀន ឲ្យតែត្រូវនឹងប្រធាន ហើយគួរផ្ទៀងផ្ទាត់ឈ្មោះតួអង្គ និងអ្នកនិពន្ធជាមួយសៀវភៅសិក្សា។"}]'::jsonb, 'ai-generated', 'Answer key written by AI (Claude) for Meh Rean from the typed question; not checked by a teacher.', 'needs-review')
on conflict (question_id) do update set answer = excluded.answer, steps = excluded.steps, source = excluded.source
  where public.question_solutions.origin = 'ai-generated' and public.question_solutions.verification <> 'verified';

