insert into public.question_solutions (question_id, answer, correct_choice, numeric_answer, numeric_tolerance, steps, origin, source, verification)
values ('bacc2020-2021-4000-8000-000000000001', 'អត្ថបទគំរូ (AI)៖ ការតស៊ូព្យាយាមដោយមិនរាថយ ជាគុណសម្បត្តិដែលធ្វើឲ្យមនុស្សឆ្លងផុតឧបសគ្គ ហើយទទួលបានជោគជ័យក្នុងជីវិត។ ឧទាហរណ៍៖ កុលាបប៉ៃលិន សូផាត រាមកេរ្តិ៍។ ចុច «Show the working» ដើម្បីអានទាំងស្រុង។', null, null, null, '[{"content":"ទម្រង់៖ សេចក្តីផ្តើម (លំនាំ ចំណូល ចំណោទបញ្ហា) · តួសេចក្តី (ពន្យល់ពាក្យ ពន្យល់ន័យ បំណកស្រាយ ឧទាហរណ៍បីរឿង សរុបមតិ) · សេចក្តីបញ្ចប់ (វាយតម្លៃ និងមតិផ្ទាល់ខ្លួន)។"},{"content":"សេចក្តីផ្តើម៖ គ្មានជោគជ័យណាមកដោយងាយទេ។ មនុស្សដែលទទួលជោគជ័យ សុទ្ធតែធ្លាប់ជួបការលំបាក តែមិនបោះបង់។ ហេតុនេះមានទស្សនៈថា «ការតស៊ូព្យាយាមមិនរាថយគឺជាគុណសម្បត្តិដើម្បីទទួលបានជោគជ័យក្នុងជីវិត»។"},{"content":"ពន្យល់ពាក្យ និងន័យ៖ ការតស៊ូព្យាយាម គឺការខំប្រឹងប្រែងពុះពារការលំបាក។ មិនរាថយ គឺមិនបោះបង់ មិនដកថយ។ គុណសម្បត្តិ គឺចរិតល្អ ឬសមត្ថភាពដែលមានតម្លៃ។ ជោគជ័យ គឺការសម្រេចបាននូវគោលដៅ។ ទស្សនៈនេះមានន័យថា អ្នកដែលព្យាយាមដោយមិនបោះបង់ នឹងសម្រេចគោលដៅក្នុងជីវិត។"},{"content":"បំណកស្រាយ៖ ក្នុងជីវិត យើងជួបឧបសគ្គ៖ ភាពក្រីក្រ ការបរាជ័យ ជំងឺ ឬការមើលងាយ។ អ្នកដែលមានការតស៊ូ ចាត់ទុកបរាជ័យជាមេរៀន ហើយបន្តដំណើរ។ ការតស៊ូល្អត្រូវមានគោលដៅច្បាស់ ផែនការ ការអត់ធ្មត់ និងសុចរិតភាព។ ផលរបស់វា៖ ជោគជ័យក្នុងការសិក្សា ការងារ គ្រួសារ និងការចូលរួមអភិវឌ្ឍប្រទេស។"},{"content":"ឧទាហរណ៍ទី១៖ រឿងកុលាបប៉ៃលិន (ញ៉ុក ថែម)៖ ចៅចិត្ត ជាយុវជនក្រីក្រ ខិតខំធ្វើការដោយស្មោះត្រង់ និងរៀនចេះលេខ ចេះភាសា។ លោកហ្លួងរតនសម្បត្តិ ឃើញពីសមត្ថភាព និងចរិតល្អរបស់គាត់ ក៏ទុកចិត្ត ហើយលើកកូនស្រីឲ្យរៀបការជាមួយ។ ការងារ និងការព្យាយាមបាននាំឲ្យចៅចិត្តមានជីវិតសុខសប្បាយ។"},{"content":"ឧទាហរណ៍ទី២៖ រឿងសូផាត (រីម គីន)៖ សូផាត ជាក្មេងដែលជួបការលំបាកតាំងពីតូច តែមិនបោះបង់ទេ។ គាត់តស៊ូរៀនសូត្រ ទ្រាំទ្រការលំបាក រហូតមានចំណេះ និងជីវិតល្អប្រសើរ។ ការតស៊ូ និងការសិក្សាបានផ្លាស់ប្តូរវាសនារបស់គាត់។"},{"content":"ឧទាហរណ៍ទី៣៖ រឿងរាមកេរ្តិ៍៖ ព្រះរាមរៀនវិជ្ជាពីឥសី ហើយព្រមចេញទៅនៅព្រៃ ដើម្បីរក្សាពាក្យសច្ចៈរបស់ព្រះបិតា។ ពេលនាងសីតាត្រូវក្រុងរាពណ៍ចាប់ ព្រះអង្គមិនបោះបង់ទេ តែតស៊ូ ប្រមូលកម្លាំង និងរកដំណោះស្រាយ រហូតជួយនាងបានវិញ។"},{"content":"សរុបមតិ៖ តួអង្គទាំងបីសុទ្ធតែជួបការលំបាក តែដោយការតស៊ូមិនរាថយ ពួកគេទទួលបានជោគជ័យ។ ដូច្នេះទស្សនៈខាងលើពិតជាត្រឹមត្រូវ។"},{"content":"សេចក្តីបញ្ចប់៖ ទស្សនៈនេះមានតម្លៃអប់រំខ្ពស់។ ក្នុងនាមជាសិស្ស ទោះមេរៀនពិបាក ឬលទ្ធផលមិនល្អម្តងម្កាល យើងត្រូវតស៊ូបន្ត ដើម្បីសម្រេចក្តីស្រមៃរបស់ខ្លួន។"},{"content":"ចំណាំ៖ នេះជាអត្ថបទគំរូមួយក្នុងចំណោមចម្លើយល្អៗជាច្រើន។ សិស្សអាចលើករឿងផ្សេងទៀតដែលបានរៀន ឲ្យតែត្រូវនឹងប្រធាន ហើយគួរផ្ទៀងផ្ទាត់ឈ្មោះតួអង្គ និងអ្នកនិពន្ធជាមួយសៀវភៅសិក្សា។"}]'::jsonb, 'ai-generated', 'Answer key written by AI (Claude) for Meh Rean from the typed question; not checked by a teacher.', 'needs-review')
on conflict (question_id) do update set answer = excluded.answer, steps = excluded.steps, source = excluded.source
  where public.question_solutions.origin = 'ai-generated' and public.question_solutions.verification <> 'verified';

insert into public.exam_papers (id, subject_id, year, title_en, title_km, duration_minutes, duration_source, origin, source, verification)
values ('bacc2020-2019-4000-8000-000000000000', 'kh-grade12-social-khmer-literature', 2019, 'BacII 2019: Khmer literature (social science track)', 'វិញ្ញាសាអក្សរសាស្ត្រខ្មែរ បាក់ឌុបឆ្នាំ២០១៩ (ថ្នាក់វិទ្យាសាស្ត្រសង្គម)', 150, 'Printed on the paper: រយៈពេល ១៥០ នាទី', 'official', 'BacII 2019 (2019-08-19), social science track khmer literature, Ministry of Education, Youth and Sport. Typed by Meh Rean from one copy: retyped by ជៀប គន្ធា (github.com/HELMAB/bacii). Not yet checked against the Ministry''s original.', 'needs-review')
on conflict (id) do update set title_en = excluded.title_en, title_km = excluded.title_km, duration_minutes = excluded.duration_minutes,
  duration_source = excluded.duration_source, source = excluded.source;

